/**
 * Action Bar for HivePress - settings screen.
 *
 * Three jobs:
 *
 * 1. The colour fields get a real picker with a typable hex box.
 * 2. The shared settings chrome - the quick-links anchor nav, the floating Save control and the
 *    back-to-top button. That block is copied from the reference implementation
 *    (account-menu-enhancer-for-hivepress, assets/js/backend.js) and only the two constants in
 *    CHROME differ.
 * 3. Each bar's section is shown only while its enabling checkbox is ticked.
 * 4. Each bar's items are drawn as cards - the house style from Account Menu Enhancer - with a
 *    header strip naming the item and folding its fields. See ITEM CARDS below.
 *
 * Despite the name this file is not minified, and neither is the chrome block in
 * backend.min.css. There is no build step in this plugin; the names are historical.
 */

/* global hpabBackendData */

( function( $ ) {
	'use strict';

	/**
	 * Expands #abc to #aabbcc and adds a missing hash.
	 *
	 * The HivePress colour field's pattern only accepts six digits, and constraint validation runs
	 * before any submit handler could correct the value, so shorthand has to be expanded as it is
	 * typed rather than on submit.
	 */
	function expandHex( value ) {
		var hex = $.trim( String( value === undefined || value === null ? '' : value ) );

		if ( ! hex ) {
			return '';
		}

		if ( hex.charAt( 0 ) !== '#' ) {
			hex = '#' + hex;
		}

		if ( /^#[0-9a-fA-F]{3}$/.test( hex ) ) {
			return '#' + hex[ 1 ] + hex[ 1 ] + hex[ 2 ] + hex[ 2 ] + hex[ 3 ] + hex[ 3 ];
		}

		return hex;
	}

	/* ======================================================================
	 * SHARED SETTINGS CHROME
	 *
	 * Three pieces of furniture for a long settings tab: the quick-links
	 * anchor nav, a floating Save control and a back-to-top button. Written
	 * to be copied verbatim into the other plugins, so everything below is
	 * self-contained and the only plugin-specific values are the two
	 * constants in CHROME.
	 *
	 * THE HOUSE RULE THIS IMPLEMENTS (resources/hivepress-settings.md, "The
	 * settings anchor nav: one shared marker class", 2026-08-30). Several of
	 * these plugins can decorate one settings screen, so each piece carries
	 * TWO classes: a shared marker that is never styled and exists only so
	 * siblings can find it (`hp-settings-nav`, `hp-settings-save`,
	 * `hp-settings-top`), plus the plugin's own prefixed class carrying all
	 * the CSS. Before rendering a piece, test for its marker with an EXACT
	 * class selector and stand down if a sibling got there first, so the
	 * owner sees one of each however many extensions are active.
	 *
	 * The exact test is the point. The old convention was the substring
	 * `nav[class*="settings-nav"]`, which was blind to three of the plugins
	 * it was meant to see - Account Menu Enhancer's own nav was called
	 * `amehp-section-nav` - and it failed silently.
	 * ================================================================== */

	var CHROME = {
		// This plugin's own class prefix and the field prefix that says the
		// rendered tab belongs to it. The only two lines to change on a copy.
		prefix: 'hpab',
		fieldPrefix: 'hp_action_bar_',
	};

	/*
	 * The only thing in this block that reaches outside itself, and it is
	 * a read of one localised object with a fallback for every string. That
	 * is deliberate: the block is copied verbatim across the extension
	 * family, so anything it depended on would have to be copied with it,
	 * and a copy that landed without its dependency would break nothing
	 * until somebody opened that plugin's settings screen.
	 */
	function chromeLabels() {
		return ( window.hpabBackendData && window.hpabBackendData.labels ) || {};
	}

	/**
	 * The settings form, but only when this plugin's tab is the one rendered.
	 *
	 * Gating on our own fields rather than on heading count, because a count
	 * is true of every HivePress tab: Geolocation Plus 1.1.0 gated that way
	 * and decorated other plugins' tabs until 1.1.1.
	 *
	 * @return {Element|null}
	 */
	function chromeForm() {
		var form = document.querySelector( '.hp-page form.hp-form--table' );

		if ( ! form || ! form.querySelector( '[name^="' + CHROME.fieldPrefix + '"]' ) ) {
			return null;
		}

		return form;
	}

	/**
	 * The quick-links anchor nav.
	 *
	 * WordPress renders settings sections as bare <h2>s through
	 * do_settings_sections(), with no hook to add anchors, so the ids and the
	 * nav have to be added here.
	 *
	 * @param {Element} form Settings form.
	 */
	function addSectionNav( form ) {
		if ( document.querySelector( 'nav.hp-settings-nav' ) ) {
			return;
		}

		// Direct children only. A settings section is a direct child of the
		// form; an h2 nested inside a panel or a card is not a section and
		// must not become a quick link.
		var headings = form.querySelectorAll( ':scope > h2' );

		if ( headings.length < 2 ) {
			return;
		}

		var nav = document.createElement( 'nav' ),
			navLabel = chromeLabels().jumpTo || 'Jump to a section:';

		nav.className = 'hp-settings-nav ' + CHROME.prefix + '-settings-nav';

		/*
		 * The bar opens with its own wording, not just an aria-label.
		 *
		 * A row of pills with nothing in front of it reads as decoration, and
		 * the one audience that was told what it is - a screen reader, through
		 * the aria-label - is the one audience that could not see the pills
		 * anyway. The visible text is part of the house chrome spec
		 * (resources/hivepress-settings.md, "The settings anchor nav"), so it
		 * carries its own class for the sibling plugins to copy, and the
		 * aria-label is dropped: the text now names the nav for everybody, and
		 * leaving both would have a screen reader announce the name twice.
		 */
		var label = document.createElement( 'span' );

		label.className = CHROME.prefix + '-settings-nav__label';
		label.textContent = navLabel;

		nav.appendChild( label );

		headings.forEach( function ( heading, index ) {

			/*
			 * Reuse the id WordPress already put on the heading and mint one
			 * only where there is none. Overwriting it breaks every link,
			 * bookmark and sibling script pointing at the real
			 * `wp-settings-section-{name}` id, which is what the first
			 * version of this nav did.
			 */
			if ( ! heading.id ) {
				heading.id = CHROME.prefix + '-section-' + index;
			}

			heading.classList.add( CHROME.prefix + '-section-heading' );

			if ( 0 === index ) {
				heading.classList.add( CHROME.prefix + '-section-heading--first' );
			}

			var link = document.createElement( 'a' );

			link.href = '#' + heading.id;

			// textContent on both ends, so heading markup can never become
			// link markup.
			link.textContent = heading.textContent;

			nav.appendChild( link );
		} );

		/*
		 * A link for settings that arrive BEFORE the first heading.
		 *
		 * HivePress core registers its Geolocation section with no `title`
		 * (hivepress-geolocation/includes/configs/settings.php, section
		 * `restrictions`), so WordPress renders no <h2> and its fields open the
		 * tab as an unheaded table. Without this they are the one group on the
		 * page the nav cannot reach.
		 *
		 * Only a real settings table qualifies. Notifications opens its form
		 * with its own live-preview panel, which is not a group of settings and
		 * must never become a quick link - hence `table.form-table` rather than
		 * "whatever comes first".
		 *
		 * The scroll offset is copied from the first heading rather than
		 * restated here, so it keeps matching whatever each plugin's CSS sets
		 * for the sticky nav and the admin bar.
		 */
		var leading = form.querySelector( ':scope > table.form-table' );

		if ( leading &&
			( leading.compareDocumentPosition( headings[ 0 ] ) & Node.DOCUMENT_POSITION_FOLLOWING ) ) {

			if ( ! leading.id ) {
				leading.id = CHROME.prefix + '-section-default';
			}

			leading.style.scrollMarginTop = window.getComputedStyle( headings[ 0 ] ).scrollMarginTop;

			var leadingLink = document.createElement( 'a' );

			leadingLink.href = '#' + leading.id;
			leadingLink.textContent = chromeLabels().defaultSettings || 'Default Settings';

			// After the "Jump to a section:" label, ahead of the real sections,
			// because that is where these fields sit on the page.
			nav.insertBefore( leadingLink, nav.children[ 1 ] || null );
		}

		/*
		 * The TOP of the form, not merely above the first heading.
		 *
		 * Those are the same element on most tabs, so this looked correct
		 * everywhere it was checked. They are not the same on the Geolocation
		 * tab: HivePress core registers its own section there with no `title`
		 * (hivepress-geolocation/includes/configs/settings.php, the
		 * `restrictions` section), so WordPress renders no <h2> for it and its
		 * fields sit in a leading table with nothing to anchor to. Inserting
		 * before headings[0] therefore put the nav BELOW core's own settings,
		 * which reads as a nav belonging only to this plugin's sections.
		 *
		 * Core's unheaded fields still get no link, because there is no heading
		 * to name one after and inventing a visible heading core chose not to
		 * have is not this plugin's call. With the nav at the top they sit
		 * directly beneath it, so a link would scroll nowhere anyway.
		 */
		form.insertBefore( nav, form.firstElementChild );
	}

	/**
	 * The floating Save control.
	 *
	 * It submits the real form rather than carrying any save logic of its
	 * own: requestSubmit() runs the same validation and the same submit
	 * handlers as pressing the button at the bottom of the page, so there is
	 * only ever one way to save. The real button stays exactly where it was.
	 *
	 * @param {Element} form Settings form.
	 */
	function addFloatingSave( form ) {
		if ( document.querySelector( '.hp-settings-save' ) ) {
			return;
		}

		var submit = form.querySelector( 'input[type="submit"], button[type="submit"]' );

		if ( ! submit ) {
			return;
		}

		var button = document.createElement( 'button' ),
			icon = document.createElement( 'span' ),
			text = document.createElement( 'span' ),
			label = chromeLabels().save || 'Save Changes';

		button.type = 'button';

		/*
		 * Core's own button classes, so WordPress paints it.
		 *
		 * This control IS the form's Save button, moved somewhere reachable,
		 * so it has to look like it - and "looks like it" is not one colour.
		 * Every user can pick an Admin Colour Scheme under Users > Profile,
		 * and each scheme repaints .wp-core-ui .button-primary. Painting our
		 * own #2271b1 matched the default scheme and nothing else: measured on
		 * 2026-08-30 under Modern, the real button was rgb(56,88,233) and this
		 * tab rgb(34,113,177), side by side on the same screen. The prefixed
		 * class is kept for layout only.
		 */
		button.className = 'hp-settings-save ' + CHROME.prefix + '-settings-save button button-primary';
		button.setAttribute( 'aria-label', label );

		icon.className = 'dashicons dashicons-saved';
		icon.setAttribute( 'aria-hidden', 'true' );

		text.className = CHROME.prefix + '-settings-save__text';
		text.textContent = label;

		button.appendChild( icon );
		button.appendChild( text );

		button.addEventListener( 'click', function () {

			// requestSubmit() fires the submit event and the browser's own
			// validation; form.submit() would skip both. Older browsers
			// without it get the real button pressed instead, which is the
			// same thing by a longer route.
			if ( form.requestSubmit ) {
				form.requestSubmit( submit );
			} else {
				submit.click();
			}
		} );

		document.body.appendChild( button );
	}

	/**
	 * The back-to-top button.
	 *
	 * Hidden until the page has actually scrolled, so it never covers
	 * anything on a tab short enough not to need it.
	 */
	function addBackToTop() {
		if ( document.querySelector( '.hp-settings-top' ) ) {
			return;
		}

		var button = document.createElement( 'button' ),
			icon = document.createElement( 'span' ),
			label = chromeLabels().backToTop || 'Back to top';

		button.type = 'button';

		// Core's secondary button, for the same reason as the Save tab above:
		// its blue is the scheme's blue, not a hex of ours.
		button.className = 'hp-settings-top ' + CHROME.prefix + '-settings-top button';
		button.setAttribute( 'aria-label', label );
		button.title = label;
		button.hidden = true;

		icon.className = 'dashicons dashicons-arrow-up-alt2';
		icon.setAttribute( 'aria-hidden', 'true' );

		button.appendChild( icon );

		button.addEventListener( 'click', function () {

			// A reader who has asked for reduced motion is asking not to be
			// moved through a long page; "auto" jumps instead of animating.
			var reduced = window.matchMedia && window.matchMedia( '(prefers-reduced-motion: reduce)' ).matches;

			window.scrollTo( {
				top: 0,
				behavior: reduced ? 'auto' : 'smooth',
			} );

			// Focus follows the scroll, so a keyboard user carries on from the
			// top of the page rather than from a button that is now off screen.
			var heading = document.querySelector( '.hp-page__title' );

			if ( heading ) {
				heading.setAttribute( 'tabindex', '-1' );
				heading.focus( { preventScroll: true } );
			}
		} );

		document.body.appendChild( button );

		/*
		 * The show/hide runs straight off the scroll event.
		 *
		 * It used to be deferred into requestAnimationFrame, which is the
		 * usual advice for scroll handlers - and it meant the button never
		 * appeared at all whenever the page was not being painted, because a
		 * browser pauses rAF on a hidden page and the callback simply never
		 * ran. Caught by measurement on 2026-08-30: document.hidden was true,
		 * the page was scrolled to 1500px, and the button stayed hidden.
		 * Nobody is looking at a page in that state, so the symptom was
		 * invisible rather than harmless - it would equally have hidden a
		 * genuine failure. The work here is two property reads and a boolean
		 * write, which is cheap enough to do on the event itself, so the
		 * optimisation bought nothing and cost correctness.
		 */
		function update() {
			button.hidden = ( window.pageYOffset || document.documentElement.scrollTop ) < 300;
		}

		window.addEventListener( 'scroll', update, { passive: true } );

		update();
	}

	/**
	 * Adds every piece of chrome, one tick after ready.
	 *
	 * The delay is deliberate: load order between plugins is not something
	 * any of them controls, so a sibling whose hook registered first may
	 * still be placing its own nav when this runs. One tick lets it finish,
	 * and the stand-down guards then see it.
	 */
	function addSettingsChrome() {
		window.setTimeout( function () {
			var form = chromeForm();

			if ( ! form ) {
				return;
			}

			addSectionNav( form );
			addFloatingSave( form );
			addBackToTop();
		}, 0 );
	}

	/* ======================================================================
	 * ITEM CARDS
	 *
	 * Each repeater row is drawn as a card: a header strip carrying the item's icon and label
	 * (or its link's name until a label is typed), folding the fields beneath it. The house rule
	 * (resources/hivepress-settings.md, "The settings card is the house style") is Account Menu
	 * Enhancer's card, and this is that plugin's addCardHeads() with two differences: the drag
	 * handle STAYS, because here the row order is the bar order and there is no other way to set
	 * it; and the title falls back to the link's name, because a bar item need not have a label.
	 *
	 * The fields themselves are never touched. They keep their names and stay in the row, so the
	 * repeater posts exactly what it posted before the strip was added.
	 * ================================================================== */

	var CARD_STORE = 'hpabCards';

	function cardLabels() {
		return ( window.hpabBackendData && window.hpabBackendData.labels ) || {};
	}

	function readCardStore() {
		try {
			return JSON.parse( window.localStorage.getItem( CARD_STORE ) ) || {};
		} catch ( error ) {
			return {};
		}
	}

	function writeCardStore( store ) {
		try {
			window.localStorage.setItem( CARD_STORE, JSON.stringify( store ) );
		} catch ( error ) {
			// Storage blocked or full; the cards still fold, they just forget on the next load.
		}
	}

	function itemRows( container ) {
		return $( container ).find( '.hp-action-bar-items table.hp-table > tbody > tr' );
	}

	// The option name a row belongs to, e.g. hp_action_bar_user_items.
	function cardFieldKey( row ) {
		var input = row.querySelector( 'input[name], select[name]' ),
			match = input && input.name ? input.name.match( /^(hp_action_bar_[a-z]+_items)\[/ ) : null;

		return match ? match[ 1 ] : '';
	}

	function cardTitle( row ) {
		var label = row.querySelector( 'input[name$="[label]"]' ),
			text = label ? $.trim( label.value ) : '';

		if ( ! text ) {
			var select = row.querySelector( 'select[name$="[link]"]' ),
				option = select ? select.options[ select.selectedIndex ] : null;

			text = option && option.value ? $.trim( option.text ) : '';
		}

		return text || cardLabels().newItem || '';
	}

	function cardIconName( row ) {
		var select = row.querySelector( 'select[name$="[icon]"]' ),
			raw = select ? $.trim( select.value || '' ).toLowerCase() : '',
			name = '';

		// Stored values may carry a family prefix from before the icon library.
		raw.split( /\s+/ ).forEach( function( token ) {
			if ( 0 === token.indexOf( 'fa-' ) ) {
				name = token.slice( 3 );
			} else if ( ! name && /^[a-z0-9-]+$/.test( token ) && -1 === [ 'fas', 'fab', 'far' ].indexOf( token ) ) {
				name = token;
			}
		} );

		return /^[a-z0-9-]+$/.test( name ) ? name : '';
	}

	/**
	 * Captions each field from its data-hpab-label, so a stacked card reads as a form rather than
	 * a row of unlabelled boxes.
	 */
	function labelFields( container ) {
		itemRows( container ).children( 'td' ).each( function() {
			var cell = $( this );

			if ( cell.children( '.hpab-field-label' ).length ) {
				return;
			}

			var control = cell.find( 'input, select' ).first(),
				text = control.length ? $.trim( control.attr( 'data-hpab-label' ) || '' ) : '';

			if ( ! text ) {
				return;
			}

			$( '<label class="hpab-field-label"></label>' ).text( text ).prependTo( cell );
		} );
	}

	function updateCardHead( row ) {
		var head = row.querySelector( ':scope > td.hpab-card-head' );

		if ( ! head ) {
			return;
		}

		head.querySelector( '.hpab-card-name' ).textContent = cardTitle( row );

		var icon = head.querySelector( '.hpab-card-icon' ),
			name = cardIconName( row );

		// Only when the icon really changed. Rewriting className on every keystroke in the label
		// strips the classes the icon library's shim added to draw the glyph, which left a broken
		// fallback-font glyph beside the SVG (Chris, 2026-09-02), and redrew for nothing.
		// The family class is not chosen here: the shared icon library's admin script replaces
		// this element with inline SVG and reads the icon's real style from its own index.
		if ( icon.getAttribute( 'data-hpab-icon' ) !== name ) {
			icon.setAttribute( 'data-hpab-icon', name );
			icon.className = name ? 'hpab-card-icon fa-fw fa-solid fa-' + name : 'hpab-card-icon';
		}
	}

	function setCardCollapsed( row, collapsed, remember ) {
		row.classList.toggle( 'hpab-card--collapsed', collapsed );

		var toggle = row.querySelector( '.hpab-card-toggle' );

		if ( toggle ) {
			toggle.setAttribute( 'aria-expanded', collapsed ? 'false' : 'true' );
			toggle.title = collapsed ? cardLabels().expand || '' : cardLabels().collapse || '';
			toggle.querySelector( '.dashicons' ).className = 'dashicons ' + ( collapsed ? 'dashicons-arrow-down-alt2' : 'dashicons-arrow-up-alt2' );
		}

		if ( remember ) {
			var key = cardFieldKey( row );

			if ( key ) {
				var store = readCardStore(),
					rows = row.parentElement ? Array.prototype.slice.call( row.parentElement.children ) : [],
					position = rows.indexOf( row );

				store[ key ] = store[ key ] || {};
				store[ key ][ position ] = collapsed ? 1 : 0;
				writeCardStore( store );
			}
		}
	}

	function addCardHeads( container ) {
		var store = readCardStore();

		itemRows( container ).each( function() {
			var row = this;

			if ( row.querySelector( ':scope > td.hpab-card-head' ) ) {
				return;
			}

			var key = cardFieldKey( row );

			if ( ! key ) {
				return;
			}

			var head = document.createElement( 'td' ),
				toggle = document.createElement( 'button' ),
				chev = document.createElement( 'span' ),
				icon = document.createElement( 'i' ),
				name = document.createElement( 'span' );

			head.className = 'hpab-card-head';
			toggle.type = 'button';
			toggle.className = 'hpab-card-toggle';
			chev.className = 'dashicons dashicons-arrow-up-alt2';
			icon.className = 'hpab-card-icon';
			icon.setAttribute( 'aria-hidden', 'true' );
			name.className = 'hpab-card-name';

			toggle.appendChild( chev );
			head.appendChild( toggle );
			head.appendChild( icon );
			head.appendChild( name );

			// After the sort-handle cell, which stays: the strip is drawn beside it.
			row.insertBefore( head, row.children[ 1 ] || null );

			head.addEventListener( 'click', function( event ) {
				// The strip is the toggle; the handle beside it is for dragging.
				if ( event.target.closest( '[data-sort]' ) ) {
					return;
				}

				setCardCollapsed( row, ! row.classList.contains( 'hpab-card--collapsed' ), true );
			} );

			updateCardHead( row );

			var rows = row.parentElement ? Array.prototype.slice.call( row.parentElement.children ) : [],
				position = rows.indexOf( row ),
				remembered = store[ key ] ? store[ key ][ position ] : undefined,
				filled = cardTitle( row ) !== ( cardLabels().newItem || '' ),
				collapsed = 'undefined' !== typeof remembered ? !! remembered : ( filled && rows.length > 1 );

			setCardCollapsed( row, collapsed, false );
		} );
	}

	function initCards( container ) {
		labelFields( container );
		addCardHeads( container );
	}

	// Keep the card headers in step with the fields that name them.
	$( document ).on( 'change input', '.hp-action-bar-items select[name$="[link]"], .hp-action-bar-items select[name$="[icon]"], .hp-action-bar-items input[name$="[label]"]', function() {
		var row = $( this ).closest( 'tr' ).get( 0 );

		if ( row ) {
			updateCardHead( row );
		}
	} );

	// Newly added repeater rows.
	$( document ).on( 'hivepress:init', function( event, container ) {
		initCards( container );
	} );

	$( function() {
		$( '.hp-action-bar-color-picker' ).each( function() {
			var field = $( this ),
				fallback = field.data( 'default-color' ),

				// The server-rendered attribute is the only honest record of whether a colour was ever
				// chosen. A native colour input reports #000000 when it is empty, so .val() cannot tell
				// "never set" apart from "deliberately black", and this has to be read before the picker
				// initialises.
				stored = $.trim( field.attr( 'value' ) || '' ),
				touched = false;

			// Core renders the colour field as a native swatch with no typable hex box. Site owners paste
			// brand hex codes and designers want the wheel, so the input becomes text and wpColorPicker
			// supplies the wheel alongside it.
			field.attr( 'type', 'text' );

			if ( $.fn.wpColorPicker ) {
				field.wpColorPicker( {
					defaultColor: fallback ? fallback : false,

					change: function() {
						touched = true;
					},

					clear: function() {
						touched = true;
					}
				} );

				// Iris seeds an empty input with its own starting colour, black, so merely opening the tab
				// and pressing Save would persist #000000 for every colour left blank.
				if ( ! stored ) {
					field.val( '' );
				}
			} else if ( ! stored && fallback ) {
				field.val( fallback );
			}

			field.on( 'change blur', function() {
				var expanded = expandHex( field.val() );

				if ( expanded !== field.val() ) {
					field.val( expanded );
				}
			} );

			field.on( 'keydown', function( event ) {
				if ( 13 === event.which ) {
					var expanded = expandHex( field.val() );

					if ( expanded !== field.val() ) {
						field.val( expanded );
					}
				}
			} );

			// Belt and braces for the same trap: if the admin never touched this picker and it is sitting
			// on Iris's default black over a field that was stored empty, send nothing rather than black.
			field.closest( 'form' ).on( 'submit', function() {
				if ( ! touched && ! stored && '#000000' === field.val().toLowerCase() ) {
					field.val( '' );
				}
			} );
		} );

		// The quick-links nav, the floating Save control and the back-to-top button. Everything
		// this used to do by hand - minting anchors, building the nav, drawing the dividers - is
		// in the shared block above, so this tab looks and behaves like every sibling's.
		addSettingsChrome();
		initCards( $( 'body' ) );

		/*
		 * Re-applied once the nav exists.
		 *
		 * bindBarToggle() below hides a whole section, and its quick link with it, but the nav is
		 * placed one tick after ready (see addSettingsChrome), so at ready time there is no link
		 * to hide yet - and the heading may not even have an id. Each toggle therefore records
		 * its own apply function here and they are all run again on the next tick, after the
		 * chrome has been placed. The timeout is registered AFTER addSettingsChrome()'s own, and
		 * two zero-delay timeouts run in the order they were registered, so this always follows
		 * it.
		 */
		var barToggles = [];

		/**
		 * Shows a bar section only while its enabling checkbox is ticked, and keeps the matching
		 * quick link in step so the navigation never points at a hidden heading.
		 *
		 * The link is looked up fresh on every call rather than held, because the nav may not
		 * exist yet on the first call - and because the nav that ends up on the page may be a
		 * sibling plugin's, whichever extension got there first. A link pointing at a section
		 * this plugin has hidden must go either way, so the lookup is on the shared marker class
		 * rather than on this plugin's own.
		 */
		function bindBarToggle( optionName, itemsPrefix ) {
			var toggle = $( 'input[name="' + optionName + '"]' ),
				field = $( '[name^="' + itemsPrefix + '"]' ).first();

			if ( ! toggle.length || ! field.length ) {
				return;
			}

			var table = field.closest( 'table.form-table' ),
				heading = table.prevAll( 'h2' ).first(),
				section = table.add( table.prevUntil( 'h2' ) ).add( heading ),
				applyToggle = function() {
					var on = toggle.is( ':checked' ),
						id = heading.attr( 'id' ),
						link = id ? $( 'nav.hp-settings-nav a[href="#' + id + '"]' ) : $();

					section.toggle( on );
					link.toggle( on );
				};

			barToggles.push( applyToggle );
			toggle.on( 'change', applyToggle );
			applyToggle();
		}

		bindBarToggle( 'hp_action_bar_enable_vendor_bar', 'hp_action_bar_vendor_items' );
		bindBarToggle( 'hp_action_bar_enable_guest_bar', 'hp_action_bar_guest_items' );
		bindBarToggle( 'hp_action_bar_enable_listing_page_bar', 'hp_action_bar_listing_page_items' );
		bindBarToggle( 'hp_action_bar_enable_vendor_page_bar', 'hp_action_bar_vendor_page_items' );

		window.setTimeout( function() {
			barToggles.forEach( function( applyToggle ) {
				applyToggle();
			} );
		}, 0 );

		$( '[name^="hp_action_bar_guest_items"],[name^="hp_action_bar_user_items"],[name^="hp_action_bar_vendor_items"],[name^="hp_action_bar_listing_page_items"],[name^="hp_action_bar_vendor_page_items"]' ).closest( '[data-component=repeater]' ).each( function() {
			var repeater = $( this ),
				applyCap = function() {
					repeater.find( '[data-add]' ).toggle( repeater.find( 'tbody tr' ).length < 5 );
				};

			repeater.on( 'click', '[data-add],[data-remove]', function() {
				window.setTimeout( applyCap, 50 );
			} );

			applyCap();
		} );
	} );
}( jQuery ) );
